//! Implementation of [`TaskContext`]
use crate::trap::trap_return;

#[repr(C)]
/// task context structure containing some registers
pub struct TaskContext {
    /// return address ( e.g. __restore ) of __switch ASM function
    ra: usize,
    /// kernel stack pointer of app
    sp: usize,
    /// callee saved registers:  s 0..11
    s: [usize; 12],
}

impl TaskContext {
    /// init task context
    pub fn zero_init() -> Self {
        Self {
            ra: 0,
            sp: 0,
            s: [0; 12],
        }
    }
    /// set Task Context{__restore ASM funciton: trap_return, sp: kstack_ptr, s: s_0..12}
    pub fn goto_trap_return(kstack_ptr: usize) -> Self {
        Self {
            ra: linker_symbol_addr!(trap_return),
            sp: kstack_ptr,
            s: [0; 12],
        }
    }
}

//! Implementation of [`TrapContext`]

use riscv::register::sstatus::{self, SPP, Sstatus};

#[repr(C)]
/// trap context structure containing sstatus, sepc and registers
pub struct TrapContext {
    /// general regs[0..31]
    pub x: [usize; 32],
    /// CSR sstatus      
    pub sstatus: Sstatus,
    /// CSR sepc
    pub sepc: usize,
    /// Addr of Page Table
    pub kernel_satp: usize,
    /// kernel stack
    pub kernel_sp: usize,
    /// Addr of trap_handler function
    pub trap_handler: usize,
}

impl TrapContext {
    /// set stack pointer to x_2 reg (sp)
    pub fn set_sp(&mut self, sp: usize) {
        self.x[2] = sp;
    }
    /// init app context
    pub fn app_init_context(
        entry: usize,
        sp: usize,
        kernel_satp: usize,
        kernel_sp: usize,
        trap_handler: usize,
    ) -> Self {
        let mut sstatus = sstatus::read(); // CSR sstatus
        sstatus.set_spp(SPP::User); //previous privilege mode: user mode
        let mut cx = Self {
            x: [0; 32],
            sstatus,
            sepc: entry,  // entry point of app
            kernel_satp,  // addr of page table
            kernel_sp,    // kernel stack
            trap_handler, // addr of trap_handler function
        };
        cx.set_sp(sp); // app's user stack pointer
        cx // return initial Trap Context of app
    }
}

The user asks about `sys_get_time(_ts: *mut TimeVal, _tz: usize)` — what is the `_tz` parameter for?

This is the classic `gettimeofday(struct timeval *tv, struct timezone *tz)` POSIX function. The second argument `tz` is a pointer to `struct timezone`, which is **obsolete/unused** (and should be NULL). It's a historical relic from 4.3BSD, where `gettimeofday` could also return the timezone (minutes west of UTC, and DST flag). POSIX.1-2008 marks `gettimeofday()` obsolescent; glibc docs say the `tz` argument is obsolete and should always be NULL; Linux kernel's `gettimeofday` syscall ignores it (and the `sys_gettimeofday` syscall exists but `tz` must be NULL or it returns -EINVAL? Let me recall).

On Linux:
- `gettimeofday(struct timeval *tv, struct timezone *tz)` — glibc wrapper. Since glibc 2.30 or so, the `tz` argument is ignored. Historically, the kernel syscall `__NR_gettimeofday` accepted a `struct timezone *tz`; the kernel's `do_gettimeofday` / `sys_gettimeofday` would write into `tz` if non-NULL? Let me recall the actual kernel behavior: `SYSCALL_DEFINE2(gettimeofday, struct timeval __user *, tv, struct timezone __user *, tz)` — it calls `do_sys_gettimeofday(tv, tz)`, which does:

```c
int do_sys_gettimeofday(struct __kernel_old_timeval *tv, struct timezone *tz)
{
