let bytes: &[u8] = unsafe {
    core::slice::from_raw_parts(
        &tv as *const TimeVal as *const u8,   // 起始地址：把 &TimeVal 强转成 *const u8
        core::mem::size_of::<TimeVal>(),      // 长度：字节数，不是元素数
    )
};
```

这三步拆开看：

```
&tv                     : &TimeVal
&tv as *const TimeVal   : *const TimeVal
   ... as *const u8     : *const u8        ← 指针类型变了，地址没变
from_raw_parts(ptr, 16) : &[u8]           ← 拿这 16 个字节当切片看
```

写成小工具函数更顺手：

```rust
fn as_bytes<T>(v: &T) -> &[u8] {
    unsafe { core::slice::from_raw_parts(v as *const T as *const u8, core::mem::size_of::<T>()) }
}
fn as_bytes_mut<T>(v: &mut T) -> &mut [u8] {
    unsafe { core::slice::from_raw_parts_mut(v as *mut T as *mut u8, core::mem::size_of::<T>()) }
}
```

**注意生命周期**：它借的是 `tv` 本身，不是拷贝。所以不能把返回值带出 `tv` 的作用域：

```rust
