    let brk0 = sbrk(0) as usize;
    let old = sbrk((4 * PAGE) as i32) as usize;
    assert_eq!(old, brk0);
    assert_eq!(sbrk(0) as usize, brk0 + 4 * PAGE);

    // 2. 逐页首次访问（触发缺页），跨页写读一致
    fill(brk0, 4, 0x30);
    assert!(check(brk0, 4, 0x30));

