    sbrk((8 * PAGE) as i32);
    fill(brk0 + 4 * PAGE, 8, 0x70);
    assert!(check(brk0, 4, 0x30));
    assert!(check(brk0 + 4 * PAGE, 8, 0x70));

    // 4. 收缩再扩张，复用同一段 VA
    sbrk(-(12 * PAGE) as i32);
    assert_eq!(sbrk(0) as usize, brk0);
    sbrk((2 * PAGE) as i32);
    fill(brk0, 2, 0xA0);
