#[macro_use]
extern crate user_lib;

use user_lib::{mmap, munmap, sbrk};

const PAGE: usize = 0x1000;

fn fill(addr: usize, bytes: usize, seed: u8) {
    for i in 0..bytes {
        unsafe { *((addr + i) as *mut u8) = seed.wrapping_add(i as u8); }
    }
}

fn verify(addr: usize, bytes: usize, seed: u8) -> bool {
    for i in 0..bytes {
        let v = unsafe { *((addr + i) as *const u8) };
        if v != seed.wrapping_add(i as u8) { return false; }
    }
    true
}

fn check(name: &str, cond: bool) -> bool {
    if cond { true } else { println!("[FAIL] {}", name); false }
}

#[no_mangle]
pub fn main() -> i32 {
    let mut ok = true;

    // 1) sbrk 只改 program_brk，不分配
    let brk0 = sbrk(0) as usize;
    let old = sbrk((4 * PAGE) as i32) as usize;
    ok &= check("sbrk return old brk", old == brk0);
    ok &= check("sbrk grows brk", sbrk(0) as usize == brk0 + 4 * PAGE);

    // 2) 首次访问触发缺页，跨页写读一致
    fill(brk0, 4 * PAGE, 0x30);
    ok &= check("heap cross-page rw", verify(brk0, 4 * PAGE, 0x30));

    // 3) 继续扩展不破坏已有数据
    sbrk((8 * PAGE) as i32);
    fill(brk0 + 4 * PAGE, 8 * PAGE, 0x70);
    ok &= check("old heap preserved", verify(brk0, 4 * PAGE, 0x30));
    ok &= check("new heap rw", verify(brk0 + 4 * PAGE, 8 * PAGE, 0x70));

    // 4) 收缩后重新扩展，复用同一段虚拟地址
    sbrk(-(12 * PAGE) as i32);
    ok &= check("sbrk shrink", sbrk(0) as usize == brk0);
    sbrk((2 * PAGE) as i32);
    fill(brk0, 2 * PAGE, 0xA0);
    ok &= check("heap reuse after shrink", verify(brk0, 2 * PAGE, 0xA0));
    sbrk(-(2 * PAGE) as i32);

    // 5) mmap 多区域
    let a = 0x2000_0000usize;
    let b = 0x3000_0000usize;
    ok &= check("mmap a", mmap(a, 3 * PAGE, 3) == 0);
    ok &= check("mmap b", mmap(b, 2 * PAGE, 3) == 0);
    fill(a, 3 * PAGE, 0x11);
    fill(b, 2 * PAGE, 0x55);
    ok &= check("mmap a rw", verify(a, 3 * PAGE, 0x11));
    ok &= check("mmap b rw", verify(b, 2 * PAGE, 0x55));

    // 6) munmap 后重新映射同一地址
    ok &= check("munmap a", munmap(a, 3 * PAGE) == 0);
    ok &= check("remap a", mmap(a, PAGE, 3) == 0);
    fill(a, PAGE, 0x99);
    ok &= check("remap a rw", verify(a, PAGE, 0x99));

    // 7) 只读映射：读可以，写应触发缺页被杀（不在本程序测）
    if ok {
        println!("lazy correctness OK!");
        0
    } else {
        println!("lazy correctness FAILED!");
        -1
    }
}
```

