#[macro_use]
extern crate user_lib;

use user_lib::{meminfo, sbrk};

const PAGE: usize = 0x1000;

fn touch(addr: usize, pages: usize) {
    for p in 0..pages {
        unsafe {
            *((addr + p * PAGE) as *mut u8) = 1;
        }
    }
}

#[no_mangle]
pub fn main() -> i32 {
    let base = meminfo();
    if base < 0 {
        println!("[lazy-mem] meminfo unavailable");
        return -1;
    }
    let brk0 = sbrk(0) as usize;
    println!("[lazy-mem] base allocated frames = {}", base);

    // 1) 申请 1000 页（约 4 MiB）但不访问：应不占物理页
    sbrk((1000 * PAGE) as i32);
    let m1 = meminfo();
    println!("[lazy-mem] after sbrk(1000 pages): {} (delta {})", m1, m1 - base);

    // 2) 只访问 10 页
    touch(brk0, 10);
    let m2 = meminfo();
    println!("[lazy-mem] after touching 10 pages: {} (delta {})", m2, m2 - m1);

