    if m4 - m3 > -990 { println!("[lazy-mem] FAIL: frames not reclaimed"); ok = false; }

    if ok { println!("[lazy-mem] all tests passed"); 0 } else { println!("[lazy-mem] FAILED"); -1 }
}
