#[macro_use]
extern crate user_lib;

use user_lib::{mmap, munmap, sbrk, sys_get_time, TimeVal};

const PAGE: usize = 0x1000;

fn now_us() -> isize {
    let mut t = TimeVal { sec: 0, usec: 0 };
    if sys_get_time(&mut t, 0) != 0 {
        return -1;
    }
    (t.sec as isize) * 1_000_000 + (t.usec as isize)
}

fn bench_sbrk(pages: usize, iters: usize) -> isize {
    let t0 = now_us();
    for _ in 0..iters {
        sbrk((pages * PAGE) as i32);
        sbrk(-((pages * PAGE) as i32));
    }
    let t1 = now_us();
    (t1 - t0) / iters as isize
}

fn bench_mmap_munmap(iters: usize) -> isize {
