{"content": "#![no_std]
#![no_main]

//! 惰性分配的物理内存测试。
//!
//! 依赖内核新增的调试系统调用 `meminfo`（syscall id = 500），
//! 返回当前已分配的物理页帧数（frame_allocator 的 allocated 计数）。
//!
//! 期望：
//!   - sbrk 申请 1000 页，不访问：帧数不增加；
//!   - 访问 10 页：帧数至少 +10（还可能有页表页）；
//!   - 访问全部 1000 页：帧数至少 +990；
//!   - 收缩 1000 页：帧数至少 -990（页表页可能不回收）。

#[macro_use]
extern crate user_lib;

use user_lib::{meminfo, sbrk};

const PAGE: usize = 0x1000;

fn touch(addr: usize, pages: usize) {
    for p in 0..pages {
        unsafe {
            *((addr + p * PAGE) as *mut u8) = 1;
        }
    }
}

#[no_mangle]
pub fn main() -> i32 {
    let base = meminfo();
    if base < 0 {
        println!("[lazy-mem] meminfo unavailable");
        return -1;
    }
    let brk0 = sbrk(0) as usize;
    println!("[lazy-mem] base allocated frames = {}", base);

    // 1) 申请 1000 页（约 4 MiB）但不访问：不应占用物理页
    sbrk((1000 * PAGE) as i32);
    let m1 = meminfo();
    println!("[lazy-mem] after sbrk(1000 pages): {} (delta {})", m1, m1 - base);

    // 2) 只访问前 10 页
    touch(brk0, 10);
    let m2 = meminfo();
    println!("[lazy-mem] after touching 10 pages: {} (delta {})", m2, m2 - m1);

    // 3) 访问剩下的 990 页
    touch(brk0 + 10 * PAGE, 990);
    let m3 = meminfo();
    println!("[lazy-mem] after touching 1000 pages: {} (delta {})", m3, m3 - m2);

    // 4) 收缩回去：数据页应被回收
    sbrk(-(1000 * PAGE) as i32);
    let m4 = meminfo();
    println!("[lazy-mem] after sbrk(-1000 pages): {} (delta {})", m4, m4 - m3);

    let mut ok = true;
    if m1 - base != 0 {
        println!("[lazy-mem] FAIL: sbrk allocated frames");
        ok = false;
    }
    if m2 - m1 < 10 {
        println!("[lazy-mem] FAIL: first touch did not allocate");
        ok = false;
    }
    if m3 - m2 < 990 {
        println!("[lazy-mem] FAIL: full touch did not allocate");
        ok = false;
    }
    if m4 - m3 > -990 {
        println!("[lazy-mem] FAIL: frames not reclaimed by sbrk shrink");
        ok = false;
    }

    if ok {
        println!("[lazy-mem] all tests passed");
        0
    } else {
        println!("[lazy-mem] FAILED");
        -1
    }
}
