{"content": "#![no_std]
#![no_main]

//! 惰性分配的时间性能测试。
//!
//! 说明：
//!   - 时间来自 `sys_get_time`，精度约 1 us（内核用 rdtime 换算）；
//!   - QEMU 上的绝对数值没有参考意义，**看趋势**：
//!       1. sbrk 增长耗时应与页数**无关**（O(1)，只改区间）；
//!       2. 首次访问的耗时随页数**线性增长**（每页一次缺页 + 建映射）；
//!       3. mmap/munmap 空操作应很快（不分配帧）。
//!
//! 注意：sbrk 的收缩路径要逐页 unmap，耗时是 O(页数)，
//! 所以这里只对「增长」计时，收缩放在计时区外。

#[macro_use]
extern crate user_lib;

use user_lib::{mmap, munmap, sbrk, sys_get_time, TimeVal};

const PAGE: usize = 0x1000;

fn now_us() -> isize {
    let mut t = TimeVal { sec: 0, usec: 0 };
    if sys_get_time(&mut t, 0) != 0 {
        return -1;
    }
    (t.sec as isize) * 1_000_000 + (t.usec as isize)
}

/// 只对 sbrk 的增长计时；收缩不计时（它要逐页 unmap）
fn bench_sbrk_grow(pages: usize, iters: usize) -> isize {
    let mut total = 0;
    for _ in 0..iters {
        let t0 = now_us();
        sbrk((pages * PAGE) as i32);
        let t1 = now_us();
        total += t1 - t0;
        sbrk(-((pages * PAGE) as i32));
    }
    total / iters as isize
}

fn bench_mmap_munmap(iters: usize) -> isize {
    let addr = 0x4000_0000usize;
    let t0 = now_us();
    for _ in 0..iters {
        mmap(addr, PAGE, 3);
        munmap(addr, PAGE);
    }
    let t1 = now_us();
    (t1 - t0) / iters as isize
}

fn bench_first_touch(pages: usize) -> isize {
    let addr = 0x5000_0000usize;
    mmap(addr, pages * PAGE, 3);
    let t0 = now_us();
    for p in 0..pages {
        unsafe {
            *((addr + p * PAGE) as *mut u8) = 1;
        }
    }
    let t1 = now_us();
    munmap(addr, pages * PAGE);
    (t1 - t0) / pages as isize
}

#[no_mangle]
pub fn main() -> i32 {
    println!("[lazy-perf] sbrk grow per call (us):");
    let sizes = [1usize, 10, 100, 1000];
    for &n in sizes.iter() {
        println!("[lazy-perf]   pages={:4} -> {} us", n, bench_sbrk_grow(n, 100));
    }

    println!(
        "[lazy-perf] mmap+munmap per pair: {} us",
        bench_mmap_munmap(200)
    );

    println!(
        "[lazy-perf] first-touch per page: {} us",
        bench_first_touch(64)
    );

    println!("[lazy-perf] done");
    0
}
", "file_path": "$PATH/rCore-Tutorial-Code/tests/lazy/ch4_lazy_perf.rs"}

