#![no_std]
#![no_main]

//! 物理内存测试（不依赖任何新增内核接口）。
//!
//! 思路：物理内存只有 128 MiB（`MEMORY_END = 0x8080_0000`），
//! 而这里申请 256 MiB 的虚拟空间：
//!   - 如果内核是 eager 分配，`sbrk`/`mmap` 在申请时就会把物理页耗尽，
//!     `frame_alloc().unwrap()` 直接 panic，内核关机；
//!   - lazy 分配下，申请只修改 `vpn_range`，立即返回；
//! 再只访问首/中/尾各一页，验证整个区间都能按需映射。
//!
//! 因此「256 MiB 申请成功 + 只访问 3 页仍能运行」本身就是
//! 「申请不占物理内存、访问才分配」的证据。

#[macro_use]
extern crate user_lib;

use user_lib::{mmap, munmap, sbrk};

const PAGE: usize = 0x1000;
const BIG: usize = 256 * 1024 * 1024; // 256 MiB > 128 MiB 物理内存

/// 写一个字节再读回，返回读到的值
fn touch(addr: usize, val: u8) -> u8 {
    unsafe {
        *(addr as *mut u8) = val;
        *(addr as *const u8)
    }
}

#[no_mangle]
pub fn main() -> i32 {
    let mut ok = true;

    // 1) 堆：一次申请 256 MiB，不访问
    let base = sbrk(0) as usize;
    let old = sbrk(BIG as i32) as usize;
    if old != base {
        println!("[lazy-mem] FAIL: sbrk return value");
        ok = false;
    }
    println!(
        "[lazy-mem] sbrk {} MiB ok (physical RAM is 128 MiB)",
        BIG / 1024 / 1024
    );

    // 2) 只访问堆的首/中/尾三页
    let probes = [base, base + BIG / 2, base + BIG - PAGE];
    for &p in probes.iter() {
        if touch(p, 0x5A) != 0x5A {
            println!("[lazy-mem] FAIL: read back at {:#x}", p);
            ok = false;
        }
    }
    println!("[lazy-mem] touched first/middle/last page of the 256 MiB heap");

    // 3) mmap 一段 256 MiB，只访问首/尾两页
    let a = 0x4000_0000usize;
    if mmap(a, BIG, 3) != 0 {
        println!("[lazy-mem] FAIL: mmap 256 MiB");
        ok = false;
    }
    if touch(a, 0x11) != 0x11 || touch(a + BIG - PAGE, 0x22) != 0x22 {
        println!("[lazy-mem] FAIL: mmap read back");
        ok = false;
    }
    println!(
        "[lazy-mem] mmap {} MiB and touched first/last page",
        BIG / 1024 / 1024
    );

    // 4) 回收
    if munmap(a, BIG) != 0 {
        println!("[lazy-mem] FAIL: munmap");
        ok = false;
    }
    sbrk(-(BIG as i32));

    if ok {
        println!("[lazy-mem] all tests passed");

