{"content": "#![no_std]
#![no_main]

//! 进一步测试：分配 vs 首次访问的开销转移，以及物理连续性的影响。
//!
//! 第一部分（开销转移）：
//!   固定申请 N = 1000 页，只访问其中 k 页（k = 1..1000）。
//!   分别测量 mmap 的时间（分配）和访问 k 页的时间（首次访问）。
//!   - eager：mmap 时就把 N 页全部映射，alloc 大、touch 小；
//!   - lazy ：mmap 只登记，alloc 小、touch 大（每页一次缺页）。
//!   两者之和的交叉点就是「懒分配划算」的临界访问比例。
//!
//! 第二部分（物理连续性）：
//!   申请两个各 512 页的区域 x、y，然后**交替**访问 x[i]、y[i]。
//!   - eager：x、y 在 mmap 时各自连续分配，物理页连续；
//!   - lazy ：缺页按 x,y,x,y 的顺序发生，两个区域的物理页交错。
//!   之后顺序读取 x，比较两种内核下的读取耗时。
//!   注意 QEMU 不模拟 DRAM row buffer / 真实 cache，因此这里测不出差异
//!   并不能说明真机上也没有差异。

#[macro_use]
extern crate user_lib;

use user_lib::{mmap, munmap, sys_get_time, TimeVal};

const PAGE: usize = 0x1000;

fn now_us() -> isize {
    let mut t = TimeVal { sec: 0, usec: 0 };
    if sys_get_time(&mut t, 0) != 0 {
        return -1;
    }
    (t.sec as isize) * 1_000_000 + (t.usec as isize)
}

/// 顺序读取 n 页，返回读到的字节和（防止被优化掉）
fn read_pass(base: usize, n: usize) -> u64 {
    let mut sum: u64 = 0;
    let p = base as *const u64;
    let words = n * PAGE / 8;
    for i in 0..words {
        sum = sum.wrapping_add(unsafe { core::ptr::read_volatile(p.add(i)) });
    }
    sum
}

#[no_mangle]
pub fn main() -> i32 {
    let n = 1000usize;
    let a = 0x4000_0000usize;

    println!("[tradeoff] alloc vs first-touch, N = {} pages", n);
    let ks = [1usize, 10, 50, 100, 200, 500, 1000];
    for &k in ks.iter() {
        let t0 = now_us();
        mmap(a, n * PAGE, 3);
        let t1 = now_us();

        let t2 = now_us();
        for j in 0..k {
            let idx = j * n / k;
            unsafe {
                *((a + idx * PAGE) as *mut u8) = 1;
            }
        }
        let t3 = now_us();

        println!(
            "[tradeoff] k={:4} alloc={:5}us touch={:5}us total={:5}us",
            k,
            t1 - t0,
            t3 - t2,
            (t1 - t0) + (t3 - t2)
        );
        munmap(a, n * PAGE);
    }

    // 第二部分：交替访问两个区域，制造物理页交错
    let n2 = 512usize;
    let x = 0x6000_0000usize;
    let y = 0x7000_0000usize;
    mmap(x, n2 * PAGE, 3);
    mmap(y, n2 * PAGE, 3);
    for i in 0..n2 {
        unsafe {
            *((x + i * PAGE) as *mut u8) = 1;
            *((y + i * PAGE) as *mut u8) = 2;
        }
    }

    let mut best = isize::MAX;
    let mut total = 0;
    let mut sum = 0u64;
    for _ in 0..10 {
        let t0 = now_us();
        sum = sum.wrapping_add(read_pass(x, n2));
        let t1 = now_us();
        total += t1 - t0;
        if t1 - t0 < best {
            best = t1 - t0;
        }
    }
    println!(
        "[tradeoff] read pass over {} pages: avg={}us best={}us (sum={})",
        n2,
        total / 10,
        best,
        sum
    );

    munmap(x, n2 * PAGE);
    munmap(y, n2 * PAGE);
    println!("[tradeoff] done");
    0
}
